/* Dhurta Suite service worker — generated by scripts/offline.ts at build time.
 *
 * It only caches the app's own code and pages. It never sees, stores or sends
 * the files you process: those stay in the page's memory.
 */
const VERSION = '__VERSION__';
const BASE = '__BASE__';
const SHELL = "__SHELL__";
const ALL = "__ALL__";

const SHELL_CACHE = `ds-shell-${VERSION}`;
const PAGE_CACHE = 'ds-pages';
const ASSET_CACHE = 'ds-assets'; // hashed, immutable file names — shared across versions
const SHARE_CACHE = 'ds-share';

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(SHELL_CACHE).then((cache) =>
      // Bypass the HTTP cache so a new version never pairs with stale files.
      cache.addAll(SHELL.map((u) => new Request(u, { cache: 'reload' }))),
    ),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set(ALL);
      for (const name of await caches.keys()) {
        if (name.startsWith('ds-shell-') && name !== SHELL_CACHE) await caches.delete(name);
      }
      // Drop tool files that no longer exist in this version.
      const assets = await caches.open(ASSET_CACHE);
      for (const req of await assets.keys()) {
        if (!keep.has(new URL(req.url).pathname)) await assets.delete(req);
      }
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data === 'SKIP_WAITING') self.skipWaiting();
});

/**
 * ignoreVary: files saved from the page with fetch() and files requested as
 * module or worker scripts send different headers; our files are static, so a
 * server's "Vary" header must not stop a cached copy from matching offline.
 */
async function fromCaches(request) {
  return (await caches.match(request, { ignoreSearch: true, ignoreVary: true })) || undefined;
}

/** Network first, cached copy when offline. Pages fall back to the app shell. */
async function networkFirst(request, cacheName, fallback) {
  try {
    const response = await fetch(request);
    if (response.ok) {
      const copy = response.clone();
      caches.open(cacheName).then((c) => c.put(request, copy));
    }
    return response;
  } catch {
    return (await fromCaches(request)) || (fallback && (await caches.match(fallback, { ignoreVary: true }))) || Response.error();
  }
}

/** Hashed assets: cache first, store on first use. */
async function handleAsset(request) {
  const hit = await fromCaches(request);
  if (hit) return hit;
  const response = await fetch(request);
  if (response.ok) {
    const copy = response.clone();
    caches.open(ASSET_CACHE).then((c) => c.put(request, copy));
  }
  return response;
}

/** Other same-origin files (icons, manifest): cached copy now, refresh in the background. */
async function handleStatic(event) {
  const cached = await fromCaches(event.request);
  const refresh = fetch(event.request)
    .then(async (response) => {
      if (response.ok) (await caches.open(SHELL_CACHE)).put(event.request, response.clone());
      return response;
    })
    .catch(() => undefined);
  if (cached) {
    event.waitUntil(refresh);
    return cached;
  }
  return (await refresh) || Response.error();
}

/** Android share sheet → keep the shared files briefly, then open the app to use them. */
async function handleShare(request) {
  try {
    const form = await request.formData();
    const files = form.getAll('files').filter((f) => typeof f !== 'string');
    const cache = await caches.open(SHARE_CACHE);
    await Promise.all(
      files.map((f, i) =>
        cache.put(`${BASE}__share/${i}`, new Response(f, { headers: { 'Content-Type': f.type || 'application/octet-stream', 'X-File-Name': encodeURIComponent(f.name || `shared-${i + 1}`) } })),
      ),
    );
    await cache.put(`${BASE}__share/count`, new Response(String(files.length)));
  } catch {
    /* fall through to the app, which reports that nothing arrived */
  }
  return Response.redirect(`${BASE}?share=1`, 303);
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // external services are never cached
  if (request.method === 'POST' && url.pathname === `${BASE}share-target`) {
    event.respondWith(handleShare(request));
    return;
  }
  if (request.method !== 'GET') return;
  if (url.pathname === `${BASE}sw.js`) return;
  if (request.mode === 'navigate') event.respondWith(networkFirst(request, PAGE_CACHE, BASE + 'index.html'));
  else if (url.pathname === `${BASE}offline.json`) event.respondWith(networkFirst(request, SHELL_CACHE));
  else if (url.pathname.startsWith(`${BASE}assets/`)) event.respondWith(handleAsset(request));
  else event.respondWith(handleStatic(event));
});
